<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {guideTopic,guideReturn,modal,dispatch,reducedMotion} from './store';
import Art from './Art.vue';
import HandbookArt from '../scenes/HandbookArt.vue';
const pages=[
 {id:'shop',name:'开门营业',art:'lin-qiao',title:'从第一位街坊开始',steps:[['叫号','按柜台绿灯，让下一位客人进店。空格或对话按钮继续交谈，听完需求后接单、买货或出售。'],['整理','上方托盘是来货，中间是谈判台，下方是自有仓库；箱包内外的正方形格子同样大，图标大小就是物品占格。拖动，或点选物品再点空格；Q / E 旋转，Esc 取消。购买后的物品仍在台面，入库后再闭店。'],['店内用具','展示柜陈列真品，维修工作台处理工单。左侧屏幕显示日期、现金和剩余工时，旁边的开关控制声音与全屏；下方任务板记录经营目标。右下抽屉打开库存、技能、采购、收藏、街区手记与设置。'],['日结','思考与整理不消耗时间。操作使用工时，闭店结算租金和维护费；工单与库存保留，食品随营业日老化。下一天恢复工时并更新来客。']]},
 {id:'trade',name:'检查与议价',art:'portable-terminal',title:'看货，再谈价格',steps:[['逐件核对','左侧选货并检查，右侧显示清单。每件旧货独立生成，检查一件不会揭示其他货物。品相与功能看基础检查，容量、纯度或完整度看扫描，真伪与原貌查序列。'],['还价','输入整批报价，客人接受时直接成交；不接受时可能还价。合理报价可换来逐步让价，极端报价只消耗耐心。接受还价使用同一份货单，换货需重新谈；刷新保留议价进度。'],['结算','标准营业同次购入至少三件享九折；批发熟客改为两件，零售货源取消批发折扣。买家有剩余预算，可按预算挑选。成交小票显示实际钱款；售出差额为货款减货品累计成本，尚未扣租金、维护和培训。谈不拢保留未成交货物与现金。']]},
 {id:'repair',name:'检测与维修',art:'micro-solder',title:'按读数动手',steps:[['定位','接单后连接检测仪，核对故障和操作位置。客户送修件独立保管，材料预付款只用于对应工单；自有旧货翻新优先使用库存耗材。'],['操作','清洁：擦过六个接点；拆装：松开螺丝、装入模块，再锁紧；校准：对齐信号与目标读数。准备不扣费，确认执行时按预览结算。参数模式可直接选择工序、位置和读数，熟练后可用快捷工序。'],['交付','排除全部故障后通电复检，再交付。古董更换原件会降低原貌，修整原件需要额外工时。维修恢复物理功能，数据完整度与历史真伪仍需分别核对。工时用完可第二天继续。']]},
 {id:'stock',name:'库存与收藏',art:'battery-pack',title:'给旧物留个位置',steps:[['买箱包','来访卖家会带来不同款式的箱包，价签同时标注外形占格和内部格子。购买后先留在谈判台，收好再闭店。按物品轮廓占格，凹角可放小件；电钻、三通阀和检修灯各有不同形状。选中后 Q 逆时针、E 顺时针旋转，凑出可用空位。普通开局仍为 144 格，可在开局词条中选择更大或更小的仓库。'],['箱中有箱','箱包本身也能放进另一个箱包。双击箱包，在鼠标附近打开格子小窗；双击里面的箱包继续打开。拖动标题栏挪开窗口，物品可在仓库与各小窗之间拖放，Q / E 旋转；触屏点选后点空格，选中箱包点“打开”。最多三层，最外层算第一层；移动整箱也要满足层数限制。关闭只收起窗口，内容保留。出售箱包前须清空。'],['标签与陈列','仓库用具位可购买标签机，在箱包小窗标题旁打印名称与颜色，区分待修、待售或不同品类；箱包不延长食品保质期。已鉴定的自有真品可以陈列，退出普通售卖；撤展后回到货架。主题和品类组合影响吸引力，同款重复收益递减。客户送修物不能当作藏品。']]},
 {id:'orders',name:'街坊与成长',art:'data-chip',title:'把生意做成招牌',steps:[['订货','每天三份需求，同时最多接两份。免费接单，按约定条件挑选实际自有库存，半个工时交货。检查工具须已持有，食品按交货日验收。最后一天闭店前交付；取消或过期保留现金与未交付货物。'],['技能与资质','通用树和维修树共享技能点。大师需维修树先投入六点，再支付两点；按任务板积累案例、参加培训与考核。维修证书和受管制货品交易许可分别取得。'],['经营权','完成街区委托后领取谢礼与回信。取得大师能力、完成联络中枢三阶段修复，再支付收购款即可通关；之后可保存结局，或免租继续经营、考古董资质和完成挑战。']]},
 {id:'save',name:'保存与补救',art:'cleaner',title:'明天还能重新开门',steps:[['保存','经营操作自动保存。换浏览器或设备前导出进度，在目标环境导入。本机与正式域名存储独立；导入后以导入点建立备份，下一个营业日起按开门状态备份。'],['欠费','基础援助维修可以零现金接取。第一次欠费后还有三次营业日结可补缴，实际期限和欠款看任务板、日结。凑够费用后完成结算才消除欠费；停业可恢复当天开门备份。'],['开局与显示','标题页的开局词条可组合正向帮助与负面挑战：资金、仓库、租金、每日工时、批发门槛和食品保质期会按选择生效，同类词条互斥。未选择时沿用标准营业。词条随本局存档保存。设置中可调整声音和减少动态，F 全屏，Esc 关闭面板；手机横屏操作。']]},
];
const initial=pages.findIndex(p=>p.id===guideTopic.value);
const spread=ref(initial<0?0:initial+1),previous=ref(spread.value),turning=ref(false),direction=ref(1);
const page=computed(()=>pages[spread.value-1]);
const oldPage=computed(()=>pages[previous.value-1]);
let turnTimer:ReturnType<typeof setTimeout>|undefined;
function turn(target:number){
 if(turning.value||target<0||target>pages.length||target===spread.value)return;
 previous.value=spread.value;direction.value=target>spread.value?1:-1;spread.value=target;
 if(!reducedMotion.value){turning.value=true;turnTimer=setTimeout(()=>turning.value=false,650);}
}
function key(e:KeyboardEvent){if(modal.value!=='help'||(e.target as HTMLElement)?.matches('input,textarea,select'))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();turn(spread.value+(e.key==='ArrowRight'?1:-1));}}
onMounted(()=>window.addEventListener('keydown',key));onUnmounted(()=>{window.removeEventListener('keydown',key);clearTimeout(turnTimer);});
function restart(){dispatch({type:'tutorial',step:0,skipped:false});modal.value='';}
</script>
<template>
 <section class="game-guide book-reader" aria-label="店长手册" :data-spread="spread">
  <div class="book-body" :class="{'is-turning':turning}">
   <HandbookArt open class="book-shell"/>
   <div class="book-leaf left-leaf">
    <div class="page-content">
     <template v-if="!page"><p class="book-kicker">雾港 · 第九街</p><h2>店长手册</h2><HandbookArt class="book-cover-inset"/><p class="book-dedication">给接下这间店的人。</p><p class="book-byline">营业 / 交易 / 修复 / 收藏</p></template>
     <template v-else><p class="book-kicker">{{String(spread).padStart(2,'0')}} / {{page.name}}</p><h2>{{page.title}}</h2><Art class="chapter-object" :id="page.art" eager/><section class="book-step"><h3>{{page.steps[0]![0]}}</h3><p>{{page.steps[0]![1]}}</p></section></template>
    </div><span class="page-number">{{spread*2+1}}</span>
   </div>
   <div class="book-leaf right-leaf">
    <div class="page-content">
     <template v-if="!page"><p class="book-kicker">CONTENTS / 目录</p><h2>从这里翻起</h2><nav class="book-contents" aria-label="教程章节"><button v-for="(p,index) in pages" :key="p.id" :disabled="turning" @click="turn(index+1)"><span>{{p.name}}</span><i></i><small>{{String(index*2+3).padStart(2,'0')}}</small></button></nav><button class="book-restart" @click="restart">重新查看店铺区域 ↗</button></template>
     <template v-else><p class="book-kicker">九街旧物 / 店用留存</p><section v-for="step in page.steps.slice(1)" :key="step[0]" class="book-step"><h3>{{step[0]}}</h3><p>{{step[1]}}</p></section><button v-if="page.id==='shop'" class="book-restart" @click="restart">重新查看店铺区域 ↗</button></template>
    </div><span class="page-number">{{spread*2+2}}</span>
   </div>
   <div v-if="turning" :class="['turn-sheet',direction<0?'turn-back':'turn-forward']" aria-hidden="true" @animationend="turning=false"><div class="sheet-face"><small>{{oldPage?.name??'店长手册'}}</small><h3>{{direction>0?(oldPage?.steps[1]?.[0]??'目录'):(oldPage?.title??'店长手册')}}</h3><p>{{direction>0?oldPage?.steps[1]?.[1]:oldPage?.steps[0]?.[1]}}</p><div class="sheet-lines"></div></div><div class="sheet-back"></div></div>
  </div>
  <footer class="book-controls"><button :disabled="turning||spread===0" @click="turn(spread-1)">← 上一页</button><button :disabled="turning||spread===0" @click="turn(0)">目录</button><span aria-live="polite">{{spread===0?'店长手册':page?.name}}</span><button :disabled="turning||spread===pages.length" @click="turn(spread+1)">下一页 →</button><button class="book-return" @click="modal=guideReturn">{{guideReturn?'返回操作':'合上手册'}} ↗</button></footer>
 </section>
</template>
<style scoped>
.book-reader{height:100%;display:flex;flex-direction:column;min-height:0;color:#303c36}.book-body{position:relative;flex:1;min-height:0;perspective:1800px;isolation:isolate;filter:drop-shadow(0 20px 24px #0007)}.book-shell{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:-1}.book-leaf{position:absolute;top:8%;bottom:9%;width:39%;display:flex;flex-direction:column;min-height:0}.left-leaf{left:8%;}.right-leaf{right:7.5%;}.page-content{min-height:0;flex:1;overflow:auto;padding-right:5px;scrollbar-width:thin;scrollbar-color:#83917e #c7c2ab66;overscroll-behavior:contain}.book-kicker{font-size:10px;letter-spacing:.12em;color:#647166;margin-bottom:18px}.book-leaf h2{font-family:Georgia,'Noto Serif SC','Microsoft YaHei',serif;font-size:30px;line-height:1.5;color:#253d35;margin-bottom:12px;font-weight:500}.book-cover-inset{height:230px;max-width:80%;display:block;margin:20px auto;filter:drop-shadow(5px 8px 5px #333b3040)}.book-dedication{text-align:center;font-family:serif;font-size:16px;color:#475749;margin-top:15px}.book-byline{text-align:center;font-size:10px;color:#6c7b68;letter-spacing:.15em;margin-top:12px}.chapter-object{display:block;width:150px;height:155px;object-fit:contain;margin:14px auto 20px;filter:drop-shadow(2px 4px 3px #293b2b30)}.book-step{margin:24px 0 30px}.book-step h3{font-size:18px;font-family:Georgia,'Microsoft YaHei',serif;color:#284738;line-height:1.6;font-weight:500;border-bottom:1px solid #74816a66;padding-bottom:8px;margin-bottom:12px}.book-step p{font-size:14px;color:#455449;line-height:2;text-align:justify}.page-number{text-align:center;font-family:Georgia,serif;font-size:11px;color:#76816d;flex-shrink:0;padding-top:8px}.book-contents{display:flex;flex-direction:column;gap:7px;margin-top:30px}.book-contents button{display:flex;align-items:baseline;gap:12px;width:100%;padding:14px 4px;border:0;background:transparent;color:#2e5144;text-align:left;min-height:44px}.book-contents button i{flex:1;border-bottom:1px dotted #88957c}.book-contents button span{font-size:16px}.book-contents button small{font-family:Georgia,serif;font-size:13px}.book-contents button:hover{background:#619b8c1f}.book-restart{border:0;border-bottom:1px solid #759580;background:transparent;font-size:12px;color:#466554;padding:6px 0;margin-top:20px}.book-controls{display:flex;align-items:center;justify-content:center;gap:12px;padding:12px 0 0;flex-shrink:0;color:#abc7bf}.book-controls button{font-size:12px;min-height:38px;background:#122f32dc;border:1px solid #668c7d;color:#c6d7c5;padding:8px 12px}.book-controls button:hover:not(:disabled){background:#345f54}.book-controls>span{font-size:11px;color:#b8c9b3;margin:0 10px;min-width:90px;text-align:center}.book-controls .book-return{border-color:#93ab8c;color:#d5dfc6;margin-left:12px}.turn-sheet{position:absolute;top:7.8%;bottom:8.8%;width:43%;z-index:5;transform-style:preserve-3d;pointer-events:none}.turn-forward{left:50%;transform-origin:left center;animation:flip-forward .55s cubic-bezier(.32,.06,.29,1) both}.turn-back{right:50%;transform-origin:right center;animation:flip-back .55s cubic-bezier(.32,.06,.29,1) both}.sheet-face,.sheet-back{position:absolute;inset:0;backface-visibility:hidden;background:linear-gradient(90deg,#c4bfab,#e6dfcb 8%,#e6dfcb 85%,#c9c6b5);box-shadow:0 4px 20px #15231b66}.sheet-face{padding:10% 12%;overflow:hidden}.sheet-face small{font-size:10px;color:#72806c}.sheet-face h3{margin:28px 0 18px;font-size:21px;color:#344e40}.sheet-face p{font-size:13px;line-height:2;color:#52614f}.sheet-back{transform:rotateY(180deg);background:linear-gradient(270deg,#c4bfab,#e6dfcb 12%,#ded9c5)}.sheet-lines{margin-top:35px;height:80px;background:repeating-linear-gradient(transparent 0 23px,#78907b20 23px 24px)}@keyframes flip-forward{0%{transform:rotateY(0deg)}90%{opacity:1}100%{transform:rotateY(-180deg);opacity:0}}@keyframes flip-back{0%{transform:rotateY(0deg)}90%{opacity:1}100%{transform:rotateY(180deg);opacity:0}}
@media(max-width:1000px){.book-leaf h2{font-size:24px}.book-step p{font-size:12px;line-height:1.85}.book-step h3{font-size:16px}.chapter-object{width:100px;height:105px;margin:10px auto}.book-contents{gap:2px;margin-top:15px}.book-contents button{padding:9px 2px}.book-contents button span{font-size:14px}.book-cover-inset{height:180px}.book-controls{gap:7px}.book-controls button{font-size:11px;padding:7px 9px}}
@media(max-height:550px){.book-leaf{top:9%;bottom:9%}.book-kicker{font-size:8px;margin-bottom:8px}.book-leaf h2{font-size:20px;margin-bottom:6px}.book-step{margin:13px 0 16px}.book-step h3{font-size:13px;padding-bottom:4px;margin-bottom:5px}.book-step p{font-size:11px;line-height:1.8}.chapter-object{width:62px;height:65px;margin:5px auto}.book-cover-inset{height:100px;margin:8px auto}.book-dedication{font-size:12px;margin-top:6px}.book-byline{font-size:8px;margin-top:5px}.book-contents{margin-top:8px;gap:0}.book-contents button{min-height:30px;padding:5px 2px}.book-contents button span{font-size:11px}.book-restart{font-size:10px;margin-top:8px}.page-number{font-size:9px;padding-top:3px}.book-controls{padding-top:5px;gap:5px}.book-controls button{min-height:32px;font-size:10px;padding:5px 8px}.book-controls>span{min-width:60px;font-size:9px;margin:0 3px}.book-controls .book-return{margin-left:4px}.sheet-face p{font-size:10px}.sheet-face h3{font-size:16px;margin:12px 0}}
@media(pointer:coarse){.book-controls button,.book-contents button,.book-restart{min-height:44px}}
</style>
